python -X utf8 -I -u -c "
import ast
for f in ('tools/b707_onset.py','tools/b709_grid.py'):
    t=ast.parse(open(f,encoding='utf-8').read())
    out=[]
    for n in t.body:
        if isinstance(n,(ast.FunctionDef,ast.ClassDef)): continue
        if isinstance(n,(ast.Import,ast.ImportFrom)):
            out.append('L%d import %s'%(n.lineno,','.join(a.name for a in n.names))); continue
        calls=[c.func.attr if isinstance(c.func,ast.Attribute) else getattr(c.func,'id','?') for c in ast.walk(n) if isinstance(c,ast.Call)]
        names=[getattr(x,'id','?') for x in n.targets] if isinstance(n,ast.Assign) else type(n).__name__
        out.append('L%d %s calls %s'%(n.lineno,names,calls))
    print(f); print(chr(10).join('    '+o for o in out))
t=ast.parse(open('tools/b707_onset.py',encoding='utf-8').read())
for n in t.body:
    if isinstance(n,ast.ClassDef) and n.name=='Combo':
        print('Combo L%d-%d methods'%(n.lineno,n.end_lineno),[m.name for m in n.body if isinstance(m,ast.FunctionDef)])
    if isinstance(n,ast.FunctionDef) and n.name in ('gram','reading','terms707'):
        print(n.name,'L%d-%d'%(n.lineno,n.end_lineno))
"

